aceholder="status"></label><label>Relation model<input data-filter="relation.model" dir="ltr" placeholder="Status"></label><label>Foreign key<input data-filter="relation.foreign_key" dir="ltr" placeholder="status_id"></label><label>Owner key<input data-filter="relation.owner_key" dir="ltr" placeholder="id"></label><label>اسم العرض<input data-filter="relation.value_name" dir="ltr" placeholder="name"></label><label>اسم المفتاح<input data-filter="relation.key_name" dir="ltr" placeholder="id"></label></div><div class="item-settings"><button type="button" class="text-button" data-add-filter-item>+ خيار ثابت</button><div data-filter-items></div></div></div></section></template>
<template id="action-template"><div class="action-card"><div class="field-card-head"><strong>Action</strong><button type="button" class="remove-row" data-remove>حذف</button></div><div class="form-grid four"><label>Key<input data-action="name_key" dir="ltr" placeholder="publish"></label><label>العربي<input data-action="name_ar" placeholder="نشر"></label><label>English<input data-action="name_en" dir="ltr" placeholder="Publish"></label><label>النوع<select data-action="type"><option value="link">link</option><option value="modal">modal</option><option value="delete">delete</option><option value="custom_modal">custom_modal</option></select></label><label>Route<input data-action="route" dir="ltr" placeholder="admin.products.publish"></label><label>Link<input data-action="link" dir="ltr" placeholder="/admin/products/#placeholder#"></label><label>Form id<input data-action="form_id" dir="ltr"></label><label>Permission<input data-action="permission" dir="ltr"></label><label>Icon<input data-action="icon" dir="ltr"></label><label>Value<input data-action="value" dir="ltr"></label><label>Operation<input data-action="operation" dir="ltr" placeholder="publish"></label><label class="check">فتح جديد<input type="checkbox" data-action="blank"></label></div><p class="action-pending" data-action-pending hidden>رابط العرض يحتاج استكمال الصفحة؛ لن يظهر في الجدول وقت التشغيل قبل توفر الوجهة.</p><div class="condition-list"><button type="button" class="text-button" data-add-condition>+ شرط ظهور AND</button><div data-conditions></div></div></div></template>
